int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip, cs;

    if (emulate_pop(ctxt, &eip) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (emulate_pop(ctxt, &cs) != X86EMUL_CONTINUE)
        return X86EMUL_UNHANDLEABLE;

    if (!ctxt->ops->get_segment(ctxt, &ctxt->regs->cs, cs))
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;

    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    return ctxt->ops->set_segment(ctxt, cs, 0, 0) ?: ctxt->ops->set_eip(ctxt, eip);
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip;
    uint16_t cs;

    if (emulate_pop(ctxt, &eip))
        return X86EMUL_UNHANDLEABLE;

    if (emulate_pop(ctxt, &cs))
        return X86EMUL_UNHANDLEABLE;

    if (!ctxt->ops->get_segment(ctxt, &cs, NULL, 0))
        return X86EMUL_UNHANDLEABLE;

    if (cs & 0xffff0000)
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = eip;
    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    uint64_t eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if ((cs & 3) == 3 && ctxt->mode != X86EMUL_MODE_VM86) {
        /* Privilege level violation */
        return X86EMUL_UNHANDLEABLE;
    }

    rc = ctxt->ops->get_segment(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    ctxt->eip = eip;
    return X86EMUL_CONTINUE;
}

int handle_far_return(struct x86_emulate_ctxt *ctxt) {
    unsigned long eip, cs;
    int rc;

    rc = emulate_pop(ctxt, &eip);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = emulate_pop(ctxt, &cs);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    /* Check for privilege level violation */
    if (ctxt->mode == X86EMUL_MODE_PROTECTED && (cs & 3) < (ctxt->regs->cs & 3)) {
        return X86EMUL_UNHANDLED;
    }

    rc = ctxt->ops->get_segment(ctxt, &ctxt->regs->cs, cs, 1);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    ctxt->regs->eip = eip;
    return X86EMUL_CONTINUE;
}
